import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter, useLocation } from "react-router";
import { it, expect } from "vitest";
import { AppRoutes } from "./AppRoutes.jsx";   // the same routes the app uses.

// Shows the current path so tests can assert the URL.
function LocationProbe() {
  return <output data-testid="location">{useLocation().pathname}</output>;
}

function renderAt(url) {
  render(
    <MemoryRouter initialEntries={[url]}>
      <AppRoutes />
      <LocationProbe />
    </MemoryRouter>
  );
}

// Link navigation, then URL, heading, focus and title.
it("navigates from C to Python", async () => {
  renderAt("/courses/c");
  await userEvent.setup().click(screen.getByRole("link", { name: "Python" }));
  const heading = await screen.findByRole("heading", { level: 1, name: "Python" });
  expect(screen.getByTestId("location")).toHaveTextContent("/courses/python");
  expect(heading).toHaveFocus();
  expect(document.title).toBe("Python | Codestead");
});

it("shows not-found for unknown paths", () => {
  renderAt("/courses/nope/extra");
  expect(screen.getByRole("heading", { name: "Page not found" })).toBeInTheDocument();
});
```

